import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in various formats to datetime.date object."""
    if not date_str or date_str.strip() == "":
        return None

    # Remove any leading/trailing whitespace
    date_str = date_str.strip()

    # Try common formats
    formats = [
        "%Y%m%d",        # 20200702
        "%Y-%m-%d",      # 2020-07-02
        "%m/%d/%Y",      # 07/02/2020
        "%d/%m/%Y",      # 02/07/2020
        "%Y%m%d%H%M%S",  # 20200702000000 (just in case)
    ]

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt).date()
        except ValueError:
            continue

    # If we get here, try to extract YYYYMMDD from longer strings
    # Look for 8 consecutive digits
    import re
    match = re.search(r'(\d{8})', date_str)
    if match:
        try:
            return datetime.strptime(match.group(1), "%Y%m%d").date()
        except ValueError:
            pass

    return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create a mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record

    return records

def process_pair(pair, facts, fda_records):
    """Process a single pair (rule_id::entity)."""
    rule_id, entity = pair.split("::", 1)
    result = {}

    for fact_name in facts[rule_id]:
        if rule_id == "fda.classified_30d":
            if fact_name == "initiation date":
                value = extract_initiation_date(entity, fda_records)
            elif fact_name == "classification date":
                value = extract_classification_date(entity, fda_records)
            else:
                value = "ABSENT"

        elif rule_id == "fda.terminated_180d":
            if fact_name == "initiation date":
                value = extract_initiation_date(entity, fda_records)
            elif fact_name == "termination date":
                value = extract_termination_date(entity, fda_records)
            else:
                value = "ABSENT"

        else:
            value = "ABSENT"

        result[fact_name] = value

    return result

def extract_initiation_date(recall_number, fda_records):
    """Extract initiation date for a recall."""
    if recall_number not in fda_records:
        return "ABSENT"

    record = fda_records[recall_number]
    date_str = record.get("recall_initiation_date", "")

    if not date_str or date_str.strip() == "":
        return "ABSENT"

    date_obj = parse_date(date_str)
    if date_obj:
        return [date_obj.isoformat(), "fda_enforcement_reports"]
    else:
        # If we can't parse it, return the raw string
        return [date_str, "fda_enforcement_reports"]

def extract_classification_date(recall_number, fda_records):
    """Extract classification date for a recall."""
    if recall_number not in fda_records:
        return "ABSENT"

    record = fda_records[recall_number]
    date_str = record.get("center_classification_date", "")

    if not date_str or date_str.strip() == "":
        return "ABSENT"

    date_obj = parse_date(date_str)
    if date_obj:
        return [date_obj.isoformat(), "fda_enforcement_reports"]
    else:
        # If we can't parse it, return the raw string
        return [date_str, "fda_enforcement_reports"]

def extract_termination_date(recall_number, fda_records):
    """Extract termination date for a recall."""
    if recall_number not in fda_records:
        return "ABSENT"

    record = fda_records[recall_number]
    date_str = record.get("termination_date", "")

    if not date_str or date_str.strip() == "":
        return "ABSENT"

    date_obj = parse_date(date_str)
    if date_obj:
        return [date_obj.isoformat(), "fda_enforcement_reports"]
    else:
        # If we can't parse it, return the raw string
        return [date_str, "fda_enforcement_reports"]

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    results = {}
    for pair in manifest["pairs"]:
        rule_id = pair.split("::", 1)[0]
        results[pair] = process_pair(pair, manifest["facts"], fda_records)

    # Output results as JSON
    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

