import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string from FDA format (YYYYMMDD) to YYYY-MM-DD."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        # Remove any commas or extra spaces
        clean = date_str.strip()
        # Handle cases like "20190709"
        if len(clean) == 8 and clean.isdigit():
            return f"{clean[:4]}-{clean[4:6]}-{clean[6:8]}"
        # Handle other formats if present (though rules specify YYYYMMDD)
        # Try parsing with common separators
        for fmt in ("%Y%m%d", "%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d"):
            try:
                dt = datetime.strptime(clean, fmt)
                return dt.strftime("%Y-%m-%d")
            except ValueError:
                continue
        return None
    except Exception:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    # Create mapping from recall_number to record(s)
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "").strip()
        if recall_num:
            records.setdefault(recall_num, []).append(record)
    return records

def extract_fact(record, fact_name):
    """Extract fact value from a single record based on fact name."""
    if fact_name == "initiation date":
        return record.get("recall_initiation_date")
    elif fact_name == "classification date":
        return record.get("center_classification_date")
    elif fact_name == "termination date":
        return record.get("termination_date")
    return None

def resolve_entity_facts(records, entity, rule_facts):
    """Resolve all facts for an entity across multiple records."""
    facts = {}
    for fact_name in rule_facts:
        values = set()
        sources = set()
        for record in records:
            value = extract_fact(record, fact_name)
            if value and value.strip():
                parsed = parse_date(value)
                if parsed:
                    values.add(parsed)
                    sources.add("fda_enforcement_reports")
        if not values:
            facts[fact_name] = "ABSENT"
        elif len(values) == 1:
            facts[fact_name] = [list(values)[0], list(sources)[0]]
        else:
            facts[fact_name] = "CONFLICT"
    return facts

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load all FDA data
    fda_records = load_fda_data(packet_dir)

    # Process each pair
    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        rule_facts = manifest["facts"][rule_id]

        # Get records for this entity
        records = fda_records.get(entity, [])
        if not records:
            # No records found for this recall number
            facts = {fact: "ABSENT" for fact in rule_facts}
        else:
            facts = resolve_entity_facts(records, entity, rule_facts)

        result[pair] = facts

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

