import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string in YYYYMMDD format to datetime object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d")
    except ValueError:
        return None

def date_to_iso(date_obj):
    """Convert datetime object to YYYY-MM-DD string."""
    if date_obj is None:
        return None
    return date_obj.strftime("%Y-%m-%d")

def load_fda_data(packet_dir):
    """Load FDA enforcement reports data from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number")
        if recall_num:
            records[recall_num] = record
    return records

def extract_fact_value(record, fact_name, rule_id):
    """Extract fact value from record based on fact name and rule."""
    if fact_name == "initiation date":
        date_str = record.get("recall_initiation_date")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj is None:
            return "ABSENT"
        return [date_to_iso(date_obj), "fda_enforcement_reports"]

    elif fact_name == "classification date":
        date_str = record.get("center_classification_date")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj is None:
            return "ABSENT"
        return [date_to_iso(date_obj), "fda_enforcement_reports"]

    elif fact_name == "termination date":
        date_str = record.get("termination_date")
        if not date_str or date_str.strip() == "":
            return "ABSENT"
        date_obj = parse_date(date_str)
        if date_obj is None:
            return "ABSENT"
        return [date_to_iso(date_obj), "fda_enforcement_reports"]

    return "ABSENT"

def process_manifest(packet_dir, manifest_path):
    """Process manifest and extract required facts."""
    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)

        # Initialize result for this pair
        if pair not in result:
            result[pair] = {}

        # Get the record for this entity
        record = fda_records.get(entity)

        if not record:
            # If no record found, all facts are ABSENT
            for fact_name in facts_by_rule.get(rule_id, []):
                result[pair][fact_name] = "ABSENT"
            continue

        # Extract each fact for this rule
        for fact_name in facts_by_rule.get(rule_id, []):
            result[pair][fact_name] = extract_fact_value(record, fact_name, rule_id)

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    result = process_manifest(packet_dir, manifest_path)

    # Output as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

