import json
import os
import sys
from datetime import datetime, timedelta
from typing import Dict, List, Tuple, Optional, Any

def parse_date(date_str: str) -> Optional[datetime]:
    """Parse date string in YYYYMMDD format to datetime object."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        return datetime.strptime(date_str.strip(), "%Y%m%d")
    except ValueError:
        return None

def load_json_file(filepath: str) -> Dict:
    """Load JSON file from given path."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def extract_facts_from_fda_report(recall_number: str, data: Dict) -> Dict[str, Any]:
    """Extract relevant facts from FDA enforcement report for a specific recall number."""
    facts = {}
    for record in data.get("results", []):
        if record.get("recall_number") == recall_number:
            # Extract initiation date
            init_date = record.get("recall_initiation_date", "")
            facts["initiation date"] = init_date

            # Extract classification date
            class_date = record.get("center_classification_date", "")
            facts["classification date"] = class_date

            # Extract termination date
            term_date = record.get("termination_date", "")
            facts["termination date"] = term_date

            # Store the document name (without extension)
            facts["_document"] = "fda_enforcement_reports"
            break
    return facts

def process_pair(pair: str, packet_dir: str, facts_map: Dict) -> Dict[str, Any]:
    """Process a single pair (rule_id::entity) and return facts with values."""
    rule_id, entity = pair.split("::")
    required_facts = facts_map[rule_id]

    # Load FDA enforcement reports
    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    if not os.path.exists(fda_file):
        raise FileNotFoundError(f"File not found: {fda_file}")

    fda_data = load_json_file(fda_file)
    extracted_facts = extract_facts_from_fda_report(entity, fda_data)

    result = {}
    document = extracted_facts.get("_document", "fda_enforcement_reports")

    for fact_name in required_facts:
        value = extracted_facts.get(fact_name, "")

        if not value or value.strip() == "":
            result[fact_name] = "ABSENT"
        else:
            # For dates, format as YYYY-MM-DD
            if fact_name in ["initiation date", "classification date", "termination date"]:
                parsed = parse_date(value)
                if parsed:
                    formatted_date = parsed.strftime("%Y-%m-%d")
                    result[fact_name] = [formatted_date, document]
                else:
                    result[fact_name] = "ABSENT"
            else:
                result[fact_name] = [value, document]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_file = sys.argv[2]

    # Load manifest
    with open(manifest_file, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_map = manifest["facts"]

    # Process all pairs
    output = {}
    for pair in pairs:
        output[pair] = process_pair(pair, packet_dir, facts_map)

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

