import json
import os
import sys
from datetime import datetime
from pathlib import Path

def parse_date(date_str):
    """Parse date string from FDA format (YYYYMMDD) or empty string."""
    if not date_str or date_str.strip() == "":
        return None
    try:
        # Handle dates like "20200121"
        return datetime.strptime(date_str.strip(), "%Y%m%d").date()
    except ValueError:
        return None

def load_fda_data(packet_dir):
    """Load FDA enforcement reports from JSON file."""
    file_path = Path(packet_dir) / "fda_enforcement_reports.json"
    with open(file_path, 'r') as f:
        data = json.load(f)

    # Create mapping from recall_number to record
    records = {}
    for record in data.get("results", []):
        recall_num = record.get("recall_number", "")
        if recall_num:
            records[recall_num] = record
    return records

def process_pair(pair, rule_id, entity, facts, fda_records):
    """Process a single pair and return fact values."""
    result = {}

    if entity not in fda_records:
        # Entity not found in records
        for fact_name in facts:
            result[fact_name] = "ABSENT"
        return result

    record = fda_records[entity]

    for fact_name in facts:
        if rule_id == "fda.classified_30d":
            if fact_name == "initiation date":
                date_str = record.get("recall_initiation_date", "")
                if not date_str or date_str.strip() == "":
                    result[fact_name] = "ABSENT"
                else:
                    date_val = parse_date(date_str)
                    if date_val:
                        result[fact_name] = [date_val.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

            elif fact_name == "classification date":
                date_str = record.get("center_classification_date", "")
                if not date_str or date_str.strip() == "":
                    result[fact_name] = "ABSENT"
                else:
                    date_val = parse_date(date_str)
                    if date_val:
                        result[fact_name] = [date_val.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

        elif rule_id == "fda.terminated_180d":
            if fact_name == "initiation date":
                date_str = record.get("recall_initiation_date", "")
                if not date_str or date_str.strip() == "":
                    result[fact_name] = "ABSENT"
                else:
                    date_val = parse_date(date_str)
                    if date_val:
                        result[fact_name] = [date_val.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

            elif fact_name == "termination date":
                date_str = record.get("termination_date", "")
                if not date_str or date_str.strip() == "":
                    result[fact_name] = "ABSENT"
                else:
                    date_val = parse_date(date_str)
                    if date_val:
                        result[fact_name] = [date_val.strftime("%Y-%m-%d"), "fda_enforcement_reports"]
                    else:
                        result[fact_name] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load FDA data
    fda_records = load_fda_data(packet_dir)

    # Process all pairs
    output = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"][rule_id]

        result = process_pair(pair, rule_id, entity, facts, fda_records)
        output[pair] = result

    # Output as JSON
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

